/**
 * The data model, ported from the Kotlin app (data/ChantState.kt). JSON field names, order, defaults and
 * decoding rules match kotlinx.serialization (`ignoreUnknownKeys = true, encodeDefaults = true`), so the
 * same stored strings and backup files round-trip between the two apps. Golden fixtures generated by the
 * Kotlin code (src/core/__fixtures__/golden.json) prove it.
 */
import {
  DecodeError,
  isArray,
  isObject,
  KJson,
  kArray,
  kBool,
  kNumber,
  kObject,
  KNull,
  kString,
} from './kjson';

/** Beads per round: a traditional mala. */
export const ROUND_SIZE = 108;
/** A milestone pulse every 27 beads, the marker beads that quarter a 108 mala. */
export const MILESTONE_INTERVAL = 27;
export const STALE_AFTER_MS = 3 * 60 * 60 * 1000;
export const MAX_TARGET_ROUNDS = 999;

export interface MantraGoal {
  id: string;
  name: string;
  targetRounds: number;
}

export interface Goal {
  id: string;
  name: string;
  mantras: MantraGoal[];
  createdAt: number;
}

export interface MantraTally {
  name: string;
  rounds: number;
  counts: number;
}

export interface SessionRecord {
  id: string;
  startTime: number;
  endTime: number;
  totalCounts: number;
  totalRounds: number;
  goalId: string | null;
  goalName: string | null;
  mantras: MantraTally[];
}

export interface ChantState {
  count: number;
  rounds: number;
  isActive: boolean;
  isPaused: boolean;
  sessionStartTime: number;
  touchCounting: boolean;
  activeGoal: Goal | null;
  currentMantraIndex: number;
  mantraRoundsCompleted: number;
  sessionId: string;
  lastUpdatedAt: number;
}

export const idleState: ChantState = Object.freeze({
  count: 0,
  rounds: 0,
  isActive: false,
  isPaused: false,
  sessionStartTime: 0,
  touchCounting: false,
  activeGoal: null,
  currentMantraIndex: 0,
  mantraRoundsCompleted: 0,
  sessionId: '',
  lastUpdatedAt: 0,
}) as ChantState;

export function chantState(partial: Partial<ChantState> = {}): ChantState {
  return { ...idleState, ...partial };
}

/** Random, collision-free ID for goals, mantras and sessions. */
export function newId(): string {
  const c = (globalThis as { crypto?: { randomUUID?: () => string } }).crypto;
  if (c?.randomUUID) return c.randomUUID();
  const hex = '0123456789abcdef';
  let s = '';
  for (let i = 0; i < 36; i++) {
    if (i === 8 || i === 13 || i === 18 || i === 23) s += '-';
    else if (i === 14) s += '4';
    else if (i === 19) s += hex[(Math.random() * 4) | 8];
    else s += hex[(Math.random() * 16) | 0];
  }
  return s;
}

// --- ChantState getters ---------------------------------------------------------------------------

export const currentRoundCount = (s: ChantState) => s.count % ROUND_SIZE;
export const progress = (s: ChantState) => currentRoundCount(s) / ROUND_SIZE;
export const currentMantra = (s: ChantState): MantraGoal | null => s.activeGoal?.mantras[s.currentMantraIndex] ?? null;

export function isCurrentMantraComplete(s: ChantState): boolean {
  const mantra = currentMantra(s);
  return mantra != null && s.mantraRoundsCompleted >= mantra.targetRounds;
}

export function isGoalComplete(s: ChantState): boolean {
  const goal = s.activeGoal;
  if (!goal) return false;
  return s.currentMantraIndex >= goal.mantras.length - 1 && isCurrentMantraComplete(s);
}

export const goalTotalRounds = (g: Goal) => g.mantras.reduce((sum, m) => sum + m.targetRounds, 0);

/** What the goal editor allows: a name, and at least one named mantra with 1 to 999 rounds. */
export function isGoalValid(g: Goal): boolean {
  return (
    g.name.trim() !== '' &&
    g.mantras.length > 0 &&
    g.mantras.every((m) => m.name.trim() !== '' && m.targetRounds >= 1 && m.targetRounds <= MAX_TARGET_ROUNDS)
  );
}

/** What was chanted of each goal mantra so far; empty without a goal. Counts add up to count. */
export function mantraTallies(s: ChantState): MantraTally[] {
  const goal = s.activeGoal;
  if (!goal) return [];
  const out: MantraTally[] = [];
  goal.mantras.forEach((mantra, index) => {
    const rounds =
      index < s.currentMantraIndex ? mantra.targetRounds : index === s.currentMantraIndex ? s.mantraRoundsCompleted : 0;
    const partial = index === s.currentMantraIndex ? currentRoundCount(s) : 0;
    const counts = rounds * ROUND_SIZE + partial;
    if (counts > 0) out.push({ name: mantra.name, rounds, counts });
  });
  return out;
}

/** History record for this session, ending at endTime. */
export function toRecord(s: ChantState, endTime: number): SessionRecord {
  return {
    id: s.sessionId === '' ? newId() : s.sessionId,
    startTime: s.sessionStartTime,
    endTime: Math.max(endTime, s.sessionStartTime),
    totalCounts: s.count,
    totalRounds: s.rounds,
    goalId: s.activeGoal?.id ?? null,
    goalName: s.activeGoal?.name ?? null,
    mantras: mantraTallies(s),
  };
}

/** Rounds and goal progress recomputed from count at 108 beads (older versions allowed other round sizes). */
export function normalizedRounds(s: ChantState): ChantState {
  const totalRounds = Math.trunc(s.count / ROUND_SIZE);
  const mantras = s.activeGoal?.mantras ?? [];
  let index = 0;
  let remaining = totalRounds;
  while (index < mantras.length - 1 && remaining >= Math.max(mantras[index].targetRounds, 1)) {
    remaining -= Math.max(mantras[index].targetRounds, 1);
    index++;
  }
  return mantras.length === 0
    ? { ...s, rounds: totalRounds }
    : { ...s, rounds: totalRounds, currentMantraIndex: index, mantraRoundsCompleted: remaining };
}

export type RestoreAction =
  | { type: 'resume'; state: ChantState }
  | { type: 'finish'; record: SessionRecord }
  | { type: 'discard' };

/** Resume a session persisted by a dead process, or save it to history if idle for 3+ hours. */
export function restoreAction(s: ChantState, now: number): RestoreAction {
  if (!s.isActive) return { type: 'discard' };
  if (now - s.lastUpdatedAt > STALE_AFTER_MS) {
    return s.count > 0 ? { type: 'finish', record: toRecord(s, s.lastUpdatedAt) } : { type: 'discard' };
  }
  return { type: 'resume', state: s };
}

export function startState(goal: Goal | null, now: number, touchCounting = false): ChantState {
  return chantState({
    isActive: true,
    sessionStartTime: now,
    touchCounting,
    activeGoal: goal,
    sessionId: newId(),
    lastUpdatedAt: now,
  });
}

export const recordDuration = (r: SessionRecord) => Math.max(r.endTime - r.startTime, 0);

// --- Counting (ChantCounter.kt) ---------------------------------------------------------------------

export type CountFeedback = 'COUNT' | 'MILESTONE' | 'ROUND' | 'SECTION' | 'GOAL';

/** Adds one count, rolling rounds every 108 beads and advancing goal mantras. Null when counting isn't allowed. */
export function increment(s: ChantState): { state: ChantState; feedback: CountFeedback } | null {
  if (!s.isActive || s.isPaused || isGoalComplete(s)) return null;
  const newCount = s.count + 1;
  const newRounds = Math.trunc(newCount / ROUND_SIZE);
  const roundCompleted = newRounds > s.rounds;
  const goal = s.activeGoal;
  let mantraIndex = s.currentMantraIndex;
  let mantraRounds = s.mantraRoundsCompleted;
  let feedback: CountFeedback = roundCompleted ? 'ROUND' : newCount % MILESTONE_INTERVAL === 0 ? 'MILESTONE' : 'COUNT';
  if (goal && roundCompleted) {
    mantraRounds++;
    const mantra = goal.mantras[mantraIndex];
    if (mantra && mantraRounds >= mantra.targetRounds) {
      if (mantraIndex < goal.mantras.length - 1) {
        feedback = 'SECTION';
        mantraIndex++;
        mantraRounds = 0;
      } else {
        feedback = 'GOAL';
      }
    }
  }
  return {
    state: { ...s, count: newCount, rounds: newRounds, currentMantraIndex: mantraIndex, mantraRoundsCompleted: mantraRounds },
    feedback,
  };
}

/** Drops repeat triggers within minIntervalMs of the last accepted one (a tap reported twice). */
export class CountDebouncer {
  static readonly DEFAULT_MIN_INTERVAL_MS = 150;
  private lastAcceptedAt: number | null = null;
  constructor(private readonly minIntervalMs = CountDebouncer.DEFAULT_MIN_INTERVAL_MS) {}
  tryAccept(nowMs: number): boolean {
    const last = this.lastAcceptedAt;
    if (last != null && nowMs - last >= 0 && nowMs - last < this.minIntervalMs) return false;
    this.lastAcceptedAt = nowMs;
    return true;
  }
}

// --- kotlinx-compatible decoding ---------------------------------------------------------------------

type Obj = Map<string, KJson>;

function prim(e: KJson | undefined, what: string): { content: string; isString: boolean } {
  if (e?.kind !== 'prim') throw new DecodeError(`Expected ${what}`);
  return e;
}

const INT_MIN = -2147483648n;
const INT_MAX = 2147483647n;
const LONG_MIN = -9223372036854775808n;
const LONG_MAX = 9223372036854775807n;

/** kotlinx JsonPrimitive.long: an integer literal, optionally with a positive exponent. */
function parseLong(content: string): bigint {
  const m = /^(-?\d+)(?:[eE]\+?(\d+))?$/.exec(content);
  if (!m) throw new DecodeError(`Not a number: ${content}`);
  let v = BigInt(m[1]);
  if (m[2] != null) v *= 10n ** BigInt(m[2]);
  if (v < LONG_MIN || v > LONG_MAX) throw new DecodeError('Long overflow');
  return v;
}

export function decodeInt(e: KJson | undefined): number {
  if (e?.kind === 'null') throw new DecodeError('null for Int');
  const v = parseLong(prim(e, 'int').content);
  if (v < INT_MIN || v > INT_MAX) throw new DecodeError('Int overflow');
  return Number(v);
}

export function decodeLong(e: KJson | undefined): number {
  if (e?.kind === 'null') throw new DecodeError('null for Long');
  return Number(parseLong(prim(e, 'long').content));
}

export function decodeBoolean(e: KJson | undefined): boolean {
  if (e?.kind === 'null') throw new DecodeError('null for Boolean');
  const c = prim(e, 'boolean').content.toLowerCase();
  if (c === 'true') return true;
  if (c === 'false') return false;
  throw new DecodeError('Not a boolean');
}

export function decodeString(e: KJson | undefined): string {
  if (e?.kind === 'null') throw new DecodeError('null for String');
  const p = prim(e, 'string');
  if (!p.isString) throw new DecodeError('String literal should be quoted');
  return p.content;
}

/** LenientIdSerializer: numbers (v1.1.0 IDs) or strings; any primitive's content, JsonNull reads as "null". */
export function decodeId(e: KJson | undefined): string {
  if (e?.kind === 'null') return 'null';
  return prim(e, 'id').content;
}

function decodeNullable<T>(e: KJson | undefined, decode: (e: KJson) => T): T | null {
  return e == null || e.kind === 'null' ? null : decode(e);
}

function obj(e: KJson | undefined): Obj {
  if (!isObject(e)) throw new DecodeError('Expected object');
  return e.entries;
}

function field<T>(o: Obj, key: string, decode: (e: KJson) => T, fallback?: () => T): T {
  const e = o.get(key);
  if (e === undefined) {
    if (fallback) return fallback();
    throw new DecodeError(`Missing field ${key}`);
  }
  return decode(e);
}

function list<T>(e: KJson, decode: (e: KJson) => T): T[] {
  if (!isArray(e)) throw new DecodeError('Expected array');
  return e.items.map(decode);
}

export function decodeMantraGoal(e: KJson): MantraGoal {
  const o = obj(e);
  return {
    id: field(o, 'id', decodeId, newId),
    name: field(o, 'name', decodeString),
    targetRounds: field(o, 'targetRounds', decodeInt),
  };
}

export function decodeGoal(e: KJson): Goal {
  const o = obj(e);
  return {
    id: field(o, 'id', decodeId, newId),
    name: field(o, 'name', decodeString),
    mantras: field(o, 'mantras', (m) => list(m, decodeMantraGoal)),
    createdAt: field(o, 'createdAt', decodeLong, () => Date.now()),
  };
}

export function decodeMantraTally(e: KJson): MantraTally {
  const o = obj(e);
  return {
    name: field(o, 'name', decodeString),
    rounds: field(o, 'rounds', decodeInt),
    counts: field(o, 'counts', decodeInt),
  };
}

export function decodeSessionRecord(e: KJson): SessionRecord {
  const o = obj(e);
  return {
    id: field(o, 'id', decodeId, newId),
    startTime: field(o, 'startTime', decodeLong),
    endTime: field(o, 'endTime', decodeLong),
    totalCounts: field(o, 'totalCounts', decodeInt),
    totalRounds: field(o, 'totalRounds', decodeInt),
    goalId: field(o, 'goalId', (v) => decodeNullable(v, decodeId), () => null),
    goalName: field(o, 'goalName', (v) => decodeNullable(v, decodeString), () => null),
    mantras: field(o, 'mantras', (m) => list(m, decodeMantraTally), () => []),
  };
}

export function decodeChantState(e: KJson): ChantState {
  const o = obj(e);
  return {
    count: field(o, 'count', decodeInt, () => 0),
    rounds: field(o, 'rounds', decodeInt, () => 0),
    isActive: field(o, 'isActive', decodeBoolean, () => false),
    isPaused: field(o, 'isPaused', decodeBoolean, () => false),
    sessionStartTime: field(o, 'sessionStartTime', decodeLong, () => 0),
    touchCounting: field(o, 'touchCounting', decodeBoolean, () => false),
    activeGoal: field(o, 'activeGoal', (v) => decodeNullable(v, decodeGoal), () => null),
    currentMantraIndex: field(o, 'currentMantraIndex', decodeInt, () => 0),
    mantraRoundsCompleted: field(o, 'mantraRoundsCompleted', decodeInt, () => 0),
    sessionId: field(o, 'sessionId', decodeString, () => ''),
    lastUpdatedAt: field(o, 'lastUpdatedAt', decodeLong, () => 0),
  };
}

// --- Encoding (encodeDefaults = true, declaration order) ---------------------------------------------

const nullable = <T>(v: T | null, enc: (v: T) => KJson) => (v == null ? KNull : enc(v));

export const encodeMantraGoal = (m: MantraGoal): KJson =>
  kObject([['id', kString(m.id)], ['name', kString(m.name)], ['targetRounds', kNumber(m.targetRounds)]]);

export const encodeGoal = (g: Goal): KJson =>
  kObject([
    ['id', kString(g.id)],
    ['name', kString(g.name)],
    ['mantras', kArray(g.mantras.map(encodeMantraGoal))],
    ['createdAt', kNumber(g.createdAt)],
  ]);

export const encodeMantraTally = (t: MantraTally): KJson =>
  kObject([['name', kString(t.name)], ['rounds', kNumber(t.rounds)], ['counts', kNumber(t.counts)]]);

export const encodeSessionRecord = (r: SessionRecord): KJson =>
  kObject([
    ['id', kString(r.id)],
    ['startTime', kNumber(r.startTime)],
    ['endTime', kNumber(r.endTime)],
    ['totalCounts', kNumber(r.totalCounts)],
    ['totalRounds', kNumber(r.totalRounds)],
    ['goalId', nullable(r.goalId, kString)],
    ['goalName', nullable(r.goalName, kString)],
    ['mantras', kArray(r.mantras.map(encodeMantraTally))],
  ]);

export const encodeChantState = (s: ChantState): KJson =>
  kObject([
    ['count', kNumber(s.count)],
    ['rounds', kNumber(s.rounds)],
    ['isActive', kBool(s.isActive)],
    ['isPaused', kBool(s.isPaused)],
    ['sessionStartTime', kNumber(s.sessionStartTime)],
    ['touchCounting', kBool(s.touchCounting)],
    ['activeGoal', nullable(s.activeGoal, encodeGoal)],
    ['currentMantraIndex', kNumber(s.currentMantraIndex)],
    ['mantraRoundsCompleted', kNumber(s.mantraRoundsCompleted)],
    ['sessionId', kString(s.sessionId)],
    ['lastUpdatedAt', kNumber(s.lastUpdatedAt)],
  ]);
